import json
n=20
g=[[0]*n for _ in range(n)]
ones=[(2,6),(3,19),(4,5),(7,1),(8,19),(12,9),(17,13),(19,15)]
for r,c in ones:g[r][c]=1
for r in range(2,9):
    for c in range(9,16):g[r][c]=2
# horizontal extensions on each side, only when no 1 lies in that direction on the same row
for r in range(2,9):
    if not any(g[r][c]==1 for c in range(9)):
        for c in range(9):g[r][c]=2
    if not any(g[r][c]==1 for c in range(16,20)):
        for c in range(16,20):g[r][c]=2
# vertical extensions from the rectangle
for c in range(9,16):
    if not any(g[r][c]==1 for r in range(2)):
        for r in range(2):g[r][c]=2
    if not any(g[r][c]==1 for r in range(9,20)):
        for r in range(9,20):g[r][c]=2
print(json.dumps(g))
